<template>
  <div class="space-y-4 min-w-0">
    <p v-if="error" class="alert-error" role="alert">{{ error }}<button class="text-link ml-2" @click="load">重新读取</button></p><p v-if="notice" class="text-sm text-status-ok" role="status">{{ notice }}</p>
    <section class="section-panel p-4"><div class="flex flex-wrap justify-between gap-3"><h2 class="font-semibold">业务数据库与应用恢复</h2><button class="btn-primary" :disabled="busy || !targets.length" @click="edit()">添加业务恢复计划</button></div><p class="mt-3 text-sm leading-6 text-surface-400">将 PostgreSQL、MySQL 或 MariaDB 备份还原到独立网络和新卷，再启动无状态应用，验证业务数据与连续三次 HTTP 请求。每次演练固定一个备份，不写入源数据库或原应用卷。</p><p class="mt-2 text-xs leading-6 text-surface-400">适用单副本数据库与无挂载的无状态应用。每份备份最多 2 GiB 原始内容，每个计划保留最近 10 份；进行中的演练引用会延长保留。RPO 从备份开始计算，RTO 从演练开始到业务验证完成计算。</p></section>
    <p v-if="loaded && !state.plans.length" class="text-sm text-surface-400">暂无业务恢复计划。现有卷归档演练仍可在“恢复演练”中查看。</p>
    <section v-for="plan in state.plans" :key="plan.id" class="section-panel p-4"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-semibold">{{ plan.projectName }} · {{ plan.config.dbService }} → {{ plan.config.appService }}</h3><span class="text-xs">{{ plan.enabled ? '已启用' : '已暂停' }} · 版本 {{ plan.version }}</span></div><p class="mt-3 text-xs text-surface-400">{{ plan.hostId }} · {{ plan.config.engine }} / {{ plan.config.database }} · {{ plan.config.assertions.length }} 项数据断言 · RPO {{ plan.config.rpoMinutes }} 分钟 / RTO {{ plan.config.rtoMinutes }} 分钟</p><p class="mt-2 text-xs text-surface-400">下次备份与演练：{{ time(plan.nextRunAt) }}</p><div class="mt-3 flex flex-wrap gap-2"><button class="btn-secondary btn-sm" :disabled="busy" @click="edit(plan)">编辑与重新审阅</button><button class="btn-secondary btn-sm" :disabled="busy || !plan.enabled || activeJob(plan.id)" @click="createBackup(plan)">创建业务备份</button><button class="btn-secondary btn-sm" :disabled="busy || !plan.enabled || activeJob(plan.id) || !usableBackups(plan).length" @click="review(plan)">选择备份并演练</button><button v-if="plan.enabled" class="btn-secondary btn-sm" :disabled="busy" @click="pause(plan)">暂停计划</button></div></section>
    <section v-if="state.backups.length" class="section-panel p-4"><h3 class="font-semibold">业务备份</h3><article v-for="backup in state.backups" :key="backup.id" class="mt-4 border-t border-surface-800 pt-3"><p class="text-sm">{{ planName(backup) }} · {{ status(backup.status) }} · {{ time(backup.createdAt) }}</p><p v-if="backup.result.sha256" class="mt-2 break-all font-mono text-xs">SHA-256 {{ backup.result.sha256 }} · {{ (backup.result.bytes / 1024).toFixed(1) }} KiB</p><p v-if="backup.error" class="mt-2 text-xs text-status-warn">{{ backup.error }}</p><button v-if="backup.status === 'outcome_unknown'" class="text-link text-xs mt-2" @click="acknowledge = { kind: 'backup', job: backup, reason: '' }">核对结果未知的备份</button></article></section>
    <section v-if="state.runs.length" class="section-panel p-4"><h3 class="font-semibold">业务恢复记录</h3><article v-for="run in state.runs" :key="run.id" class="mt-4 border-t border-surface-800 pt-3"><div class="flex flex-wrap justify-between gap-2"><p class="text-sm">{{ planName(run) }} · {{ time(run.createdAt) }}</p><strong class="text-sm" :class="run.status === 'passed' ? 'text-status-ok' : 'text-status-warn'">{{ status(run.status) }}</strong></div><p class="mt-2 text-xs">SQL {{ run.result.assertions?.filter(row => row.passed).length || 0 }} / {{ run.result.assertions?.length || 0 }} · HTTP 成功 {{ run.result.httpChecks?.filter(row => row.passed).length || 0 }} 次 · 清理 {{ run.result.cleanupComplete ? '完成' : '未完成' }}</p><p class="mt-2 text-xs text-surface-400">备份年龄 {{ minutes(run.result.backupAgeMs) }} · 业务恢复用时 {{ minutes(run.result.recoveryDurationMs) }} · RPO {{ verdict(run.result.rpoMet) }} / RTO {{ verdict(run.result.rtoMet) }}</p><p v-if="run.error" class="mt-2 text-xs text-status-warn">{{ run.error }}</p><details class="mt-2"><summary class="text-xs cursor-pointer">恢复与资源证据</summary><pre class="mt-2 max-h-80 overflow-auto whitespace-pre-wrap break-all text-xs">{{ JSON.stringify(run.result, null, 2) }}</pre></details><button v-if="run.status === 'outcome_unknown'" class="text-link text-xs mt-2" @click="acknowledge = { kind: 'run', job: run, reason: '' }">核对并关闭未知结果</button></article></section>
    <BaseModal :show="!!draft" :title="draft?.id ? '重新审阅业务恢复计划' : '添加业务恢复计划'" :close-disabled="busy" size-class="max-w-3xl" @close="draft = null"><form v-if="draft" class="space-y-4" @submit.prevent="save"><p v-if="formError" class="alert-error" role="alert">{{ formError }}</p><fieldset :disabled="busy" class="space-y-4"><label v-if="!draft.id" class="form-grid-label"><span>纳管应用</span><select v-model="targetKey" class="input w-full" required @change="choose"><option value="" disabled>选择应用与节点</option><option v-for="target in targets" :key="target.hostId + ':' + target.projectId" :value="target.hostId + ':' + target.projectId">{{ target.projectName }} · {{ target.hostId }}</option></select></label><p v-else class="text-sm">{{ draft.projectName }} · {{ draft.hostId }}<br />保存后旧版本备份不再用于新版本演练。</p><p v-if="candidateError" class="alert-error">{{ candidateError }}</p><p v-if="candidates" class="text-xs leading-6 text-surface-400">{{ candidates.limitations }}</p><BusinessRecoveryFields :key="draft.id || targetKey" v-model="draft.config" :services="services" /><label v-if="draft.config.engine !== 'postgres'" class="flex gap-2 text-sm"><input v-model="draft.noConcurrentDdl" type="checkbox" required />确认备份窗口不执行数据库结构变更</label><label v-if="draft.config.scheduleHours" class="flex gap-2 text-sm"><input v-model="scheduleApproved" type="checkbox" required />授权定时创建备份并启动隔离应用演练（至少每 24 小时）</label><label class="flex gap-2 text-sm"><input v-model="draft.enabled" type="checkbox" />启用计划</label><button class="btn-primary" :disabled="busy || !services.length || !!candidateError">保存固定目标与验收条件</button></fieldset></form></BaseModal>
    <BaseModal :show="!!runDraft" title="审阅隔离业务恢复" :close-disabled="busy" @close="runDraft = null"><form v-if="runDraft" class="space-y-4" @submit.prevent="startRun"><p v-if="formError" class="alert-error" role="alert">{{ formError }}</p><p class="text-sm">{{ runDraft.plan.projectName }} · {{ runDraft.plan.hostId }} · 版本 {{ runDraft.plan.version }}</p><label class="form-grid-label"><span>固定恢复点</span><select v-model="runDraft.backupId" class="input w-full" required><option v-for="item in usableBackups(runDraft.plan)" :key="item.id" :value="item.id">{{ time(item.result.snapshotAt) }} · {{ item.id }}</option></select></label><p class="text-xs break-all">SHA-256 {{ state.backups.find(row => row.id === runDraft.backupId)?.result.sha256 }}</p><p class="text-sm leading-6">将创建内部网络、新数据库卷和隔离应用，执行已审阅的 SQL 数据断言与 HTTP 检查。源应用卷不会挂载到演练容器。</p><button class="btn-primary" :disabled="busy">确认执行隔离恢复</button></form></BaseModal>
    <BaseModal :show="!!acknowledge" title="核对未知结果" :close-disabled="busy" @close="acknowledge = null"><form v-if="acknowledge" class="space-y-4" @submit.prevent="closeUnknown"><p class="text-sm leading-6">先在原节点核对登记资源并清理残留。关闭仅解除后续任务阻塞，不代表恢复成功。</p><p v-if="formError" class="alert-error" role="alert">{{ formError }}</p><textarea v-model="acknowledge.reason" class="input w-full" rows="4" minlength="8" maxlength="1000" required placeholder="填写实际核对与清理记录" /><button class="btn-primary" :disabled="busy">验证资源已不存在并关闭</button></form></BaseModal>
  </div>
</template>
<script setup>
import { ref, computed, toRaw, onMounted, onActivated, onDeactivated, onBeforeUnmount } from 'vue';
import { api } from '../api/client.js';
import BaseModal from './common/BaseModal.vue';
import BusinessRecoveryFields from './BusinessRecoveryFields.vue';
const state = ref({ plans: [], backups: [], runs: [] }), targets = ref([]), error = ref(''), notice = ref(''), formError = ref(''), busy = ref(false), loaded = ref(false);
const draft = ref(null), targetKey = ref(''), candidates = ref(null), candidateError = ref(''), scheduleApproved = ref(false), runDraft = ref(null), acknowledge = ref(null);
const selected = computed(() => targets.value.find(row => row.hostId + ':' + row.projectId === targetKey.value));
const services = computed(() => candidates.value?.services.filter(row => !row.unsupported).map(row => row.serviceName) || []);
let active = false, disposed = false, epoch = 0, loading = false, controller, timer, candidateController, candidateEpoch = 0;
const time = value => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '未安排';
const minutes = value => value == null ? '未知' : (value / 60000).toFixed(2) + ' 分钟';
const verdict = value => value == null ? '未验证' : value ? '达标' : '未达标';
const status = value => ({ queued: '排队中', running: '执行中', verified: '备份已校验', passed: '业务恢复通过', failed: '未通过', expired: '已过保留期', outcome_unknown: '结果未知，需核对', closed: '已核对关闭，未验证恢复' })[value] || value;
const planName = job => job.snapshot.plan.projectName;
const activeJob = id => [...state.value.backups, ...state.value.runs].some(row => row.planId === id && ['queued', 'running', 'outcome_unknown'].includes(row.status));
const usableBackups = plan => state.value.backups.filter(row => row.planId === plan.id && row.version === plan.version && row.status === 'verified');
async function load() {
  if (!active || loading || busy.value) return; const current = ++epoch; loading = true; controller = new AbortController();
  try { const [data, projects] = await Promise.all([api.getSreResource('business-recovery', controller.signal), api.getSreTargets(controller.signal)]); if (active && current === epoch) { state.value = data; targets.value = projects.targets; loaded.value = true; error.value = ''; } }
  catch (cause) { if (active && current === epoch) error.value = cause.message; }
  finally { if (current === epoch) loading = false; }
}
async function choose() {
  candidateController?.abort(); const current = ++candidateEpoch; candidateController = new AbortController(); candidates.value = null; candidateError.value = ''; if (!draft.value) return;
  if (!draft.value.id) { Object.assign(draft.value, { hostId: selected.value?.hostId, projectId: selected.value?.projectId }); draft.value.config.dbService = ''; draft.value.config.appService = ''; }
  if (!draft.value.projectId) return;
  try { const data = await api.getSreResource('business-recovery/candidates?' + new URLSearchParams({ hostId: draft.value.hostId, projectId: draft.value.projectId }), candidateController.signal); if (active && current === candidateEpoch) { candidates.value = data; if (!data.supported) candidateError.value = '此应用没有可读取的完整 Compose 工作区'; } }
  catch (cause) { if (active && current === candidateEpoch) candidateError.value = cause.message; }
}
function edit(plan) {
  formError.value = ''; scheduleApproved.value = false; targetKey.value = ''; candidates.value = null;
  draft.value = plan ? { ...structuredClone(toRaw(plan)), noConcurrentDdl: false } : { enabled: true, noConcurrentDdl: false, config: { engine: 'postgres', dbService: '', appService: '', database: '', user: 'postgres', credentialEnv: 'POSTGRES_PASSWORD', appEnvironment: { DATABASE_URL: '$DB_URL' }, assertions: [{ table: '', expectedRows: 1, column: '', equals: '' }], http: { port: 8080, path: '/health', expectedStatus: 200, bodyContains: '' }, rpoMinutes: 1440, rtoMinutes: 15, scheduleHours: 0 } };
  if (plan) void choose();
}
async function act(work, complete) {
  if (!active || busy.value) return; controller?.abort(); epoch++; loading = false; const current = epoch; busy.value = true; error.value = ''; formError.value = '';
  try { await work(); if (active && current === epoch) { complete?.(); notice.value = '操作已保存；执行结果以任务记录为准。'; } }
  catch (cause) { if (active && current === epoch) { if (draft.value || runDraft.value || acknowledge.value) formError.value = cause.message; else error.value = cause.message; } }
  finally { busy.value = false; if (active && current === epoch) void load(); }
}
function save() { const value = draft.value; if (value.config.scheduleHours && !scheduleApproved.value) { formError.value = '请确认定时授权'; return; } const body = { version: value.version, hostId: value.hostId, projectId: value.projectId, config: value.config, enabled: value.enabled, noConcurrentDdl: value.noConcurrentDdl, ...(value.config.scheduleHours ? { confirm: 'ENABLE_BUSINESS_SCHEDULE' } : {}) }; return act(() => api.sreOperation('business-recovery/plans' + (value.id ? '/' + value.id : ''), body, value.id ? 'PUT' : 'POST'), () => { draft.value = null; }); }
function createBackup(plan) { return act(() => api.sreOperation('business-recovery/plans/' + plan.id + '/backup', { confirm: 'CREATE_BUSINESS_BACKUP' })); }
function pause(plan) { return act(() => api.sreOperation('business-recovery/plans/' + plan.id + '/pause', {})); }
function review(plan) { formError.value = ''; runDraft.value = { plan, backupId: usableBackups(plan)[0]?.id }; }
function startRun() { const value = runDraft.value; return act(() => api.sreOperation('business-recovery/plans/' + value.plan.id + '/run', { confirm: 'ISOLATED_BUSINESS_RECOVERY', backupId: value.backupId }), () => { runDraft.value = null; }); }
function closeUnknown() { const value = acknowledge.value; return act(() => api.sreOperation('business-recovery/' + value.kind + '/' + value.job.id + '/acknowledge', { reason: value.reason }), () => { acknowledge.value = null; }); }
function start() { if (active || disposed) return; active = true; void load(); timer = setInterval(load, 5000); if (draft.value) void choose(); }
function stop() { active = false; controller?.abort(); candidateController?.abort(); epoch++; candidateEpoch++; loading = false; clearInterval(timer); }
onMounted(start); onActivated(start); onDeactivated(stop); onBeforeUnmount(() => { disposed = true; stop(); });
</script>
